&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience building end-to-end data pipelines: data cleaning, feature engineering, model training, validation, and deployment&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:30,&amp;quot;335559739&amp;quot;:30}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
