&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Proven record of managing complex missile defense tooling programs from concept through sustained production.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:40,&amp;quot;335559739&amp;quot;:40}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Deep experience directing fabrication vendors: SOW development, source selection, performance management, and disposition of non-conformances.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:40,&amp;quot;335559739&amp;quot;:40}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
