&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Extensive direct experience as tooling technical lead on major &lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-teams=&quot;true&quot;&gt;Space Based Interceptors&lt;/span&gt;&lt;/span&gt; programs: THAAD, PAC-3/MSE, SM-3 Block IIA, GMD/GBI, Next Generation Interceptor (NGI), JASSM, LRASM, or equivalent MDA/Army/Navy programs.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:40,&amp;quot;335559739&amp;quot;:40}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
