&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with deployable, conformal, body-mounted, or phased-array antennas.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience modeling spacecraft-level electromagnetic compatibility, coupling, interference, or antenna-to-structure interactions.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with RF measurements using vector network analyzers, spectrum analyzers, signal generators, antenna ranges, or anechoic chambers.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Familiarity with thermal, structural, vibration, thermal vacuum, and radiation considerations for space hardware.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with MATLAB, Python, or similar tools for RF analysis and simulation automation.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Active TS//SCI clearance or eligibility to obtain one.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience working in a fast-paced startup or similarly dynamic environment.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;COMPENSATION&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Base Salary:&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt; $190,000 - $275,000&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Equity + Benefits&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; including Health, Dental, Vision, HRA/HSA options, PTO and paid holidays, 401K, Parental Leave&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&lt;em&gt;&lt;span class=&quot;TextRun SCXW83253800 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW83253800 BCX0&quot;&gt;Your actual level and base salary will be&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW83253800 BCX0&quot;&gt;determined&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW83253800 BCX0&quot;&gt; on a case-by-case basis and may vary based on the following considerations: job-related knowledge and skills, education, location, and experience.&lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;span class=&quot;EOP SCXW83253800 BCX0&quot; data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;ADDITIONAL REQUIREMENTS&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Active TS//SCI clearance or eligibility to obtain one.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Work Location&lt;/strong&gt;—Successful candidates will be located near Centennial or Long Beach. While we observe a hybrid work environment, some work must be done on site.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Work environment&lt;/strong&gt;—the work environment; temperature, noise level, inside or outside, or other factors that will affect the person&#39;s working conditions while performing the job.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Physical demands&lt;/strong&gt;—the physical demands of the job, including bending, sitting, lifting and driving.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW267002851 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt;This position will be open until it is successfully filled. To &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt;submit&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt; your application, please follow the directions below.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW267002851 BCX0&quot; lang=&quot;EN-US&quot; style=&quot;color: rgb(0, 0, 0);&quot; data-contrast=&quot;none&quot;&gt; &lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt;#LI-Onsite&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;To conform to U.S. Government space technology export regulations, including the International Traffic in Arms Regulations (ITAR) you must be a U.S. citizen, lawful permanent resident of the U.S., protected individual as defined by 8 U.S.C. 1324b(a)(3), or eligible to obtain the required authorizations from the U.S. Department of State.&lt;/p&gt;
&lt;p&gt;True Anomaly is committed to equal employment opportunity on any basis protected by applicable state and federal laws. If you have a disability or additional need that requires accommodation, please do not hesitate to let us know.&lt;/p&gt;
&lt;p&gt;To protect candidates and our company from application fraud and impersonation, we use third-party tools to verify applicant identity and detect fraudulent applications. Learn more in our &lt;a href=&quot;https://www.trueanomaly.space/legal/privacy-policy&quot; target=&quot;_blank&quot;&gt;Privacy Notice&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;Space is a warfighting domain. True Anomaly seeks those with the talent and ambition to build the technology that secures it.&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;u&gt;OUR MISSION&lt;/u&gt;&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;True Anomaly delivers decisive capabilities for space superiority. We build autonomous spacecraft, advanced payloads, mission software, and space-based interceptors — enabling the U.S. and its Allies to secure the space environment and counter threats from the ultimate high ground.&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;u&gt;OUR VALUES&lt;/u&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;strong&gt;Be the offset.&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;We create asymmetric advantages with creativity and ingenuity.&lt;/li&gt;
&lt;li class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;strong&gt;What would it take?&lt;/strong&gt;&amp;nbsp;We challenge assumptions to deliver ambitious results.&lt;/li&gt;
&lt;li class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;strong&gt;It’s the people.&lt;/strong&gt; Our team is our competitive advantage and we are better together.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;BENEFITS &amp;amp; PERKS&lt;/span&gt;*&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Best-in-class healthcare: &lt;/strong&gt;100% company-paid medical, dental, and vision coverage for you and your dependents, with HSA/HRA options&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Generous time off: &lt;/strong&gt;Flexible Time Off (FTO) for exempt employees, accrued PTO of up to 25 days for non-exempt employees, plus 12 paid holidays; Parental Leave; Sick Leave&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Fuel for your day: &lt;/strong&gt;Daily catered lunch and unlimited snacks for in-office employees&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;And more: &lt;/strong&gt;401(k) retirement plan, fitness reimbursement, and Dog Fridays&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Equity participation: &lt;/strong&gt;Equity is included as part of our total compensation package, giving you an opportunity to share in the company’s success.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;*Do not apply to fixed term and temporary roles&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;u&gt;YOUR MISSION&lt;/u&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW222020915 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW222020915 BCX8&quot;&gt;As a Procurement Specialist at True Anomaly, you will own the day-to-day execution of indirect procurement — sourcing the services, tools, facilities, and operational goods that keep our teams moving. You will manage the full purchase-to-pay cycle, handle vendor relationships, and solve the supply problems that pop up without warning. This is a tactical, execution-focused role for someone who is organized, resourceful, and energized by getting things done quickly and correctly in a fast-moving environment.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW222020915 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;RESPONSIBILITIES&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Execute the full&amp;nbsp;procure-to-pay process: intake requests, issue RFQs, evaluate bids, issue purchase orders, and confirm delivery and invoicing&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Maintain an active vendor list for indirect categories, ensuring competitive options are available when needs arise&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Track open purchase orders and proactively follow up with vendors to ensure on-time delivery&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Support contract administration for indirect agreements — NDAs, MSAs, SOWs — coordinating with legal as needed&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Serve as the day-to-day point of contact for indirect vendors, managing performance expectations and resolving delivery, quality, or invoicing issues quickly&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Identify and qualify new vendors when existing suppliers cannot meet requirements on cost, lead time, or capability&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Escalate and resolve vendor disputes, short shipments, and invoice discrepancies without letting issues linger&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Maintain accurate procurement records — POs, quotes, contracts, and receipts — in the procurement system of record&lt;/li&gt;
