&lt;p&gt;&lt;strong&gt;COMPENSATION&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Base Salary: &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;$155,000 - $225,000&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Equity + Benefits&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; including Health, Dental, Vision, HRA/HSA options, PTO and paid holidays, 401K, Parental Leave&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&lt;em&gt;&lt;span class=&quot;TextRun SCXW83253800 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW83253800 BCX0&quot;&gt;Your actual level and base salary will be&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW83253800 BCX0&quot;&gt;determined&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW83253800 BCX0&quot;&gt; on a case-by-case basis and may vary based on the following considerations: job-related knowledge and skills, education, location, and experience.&lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;span class=&quot;EOP SCXW83253800 BCX0&quot; data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;ADDITIONAL REQUIREMENTS&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Work Location&lt;/strong&gt;—This is an onsite role, we are seeking candidates based near Denver, CO or Long Beach, CA.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Work environment&lt;/strong&gt;—the work environment; temperature, noise level, inside or outside, or other factors that will affect the person&#39;s working conditions while performing the job.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Physical demands&lt;/strong&gt;—the physical demands of the job, including bending, sitting, lifting and driving.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW267002851 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt;This position will be open until it is successfully filled. To &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt;submit&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt; your application, please follow the directions below. &lt;br&gt;#LI-Onsite&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;To conform to U.S. Government space technology export regulations, including the International Traffic in Arms Regulations (ITAR) you must be a U.S. citizen, lawful permanent resident of the U.S., protected individual as defined by 8 U.S.C. 1324b(a)(3), or eligible to obtain the required authorizations from the U.S. Department of State.&lt;/p&gt;
&lt;p&gt;True Anomaly is committed to equal employment opportunity on any basis protected by applicable state and federal laws. If you have a disability or additional need that requires accommodation, please do not hesitate to let us know.&lt;/p&gt;
&lt;p&gt;To protect candidates and our company from application fraud and impersonation, we use third-party tools to verify applicant identity and detect fraudulent applications. Learn more in our &lt;a href=&quot;https://www.trueanomaly.space/legal/privacy-policy&quot; target=&quot;_blank&quot;&gt;Privacy Notice&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;Space is a warfighting domain. True Anomaly seeks those with the talent and ambition to build the technology that secures it.&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;u&gt;OUR MISSION&lt;/u&gt;&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;True Anomaly delivers decisive capabilities for space superiority. We build autonomous spacecraft, advanced payloads, mission software, and space-based interceptors — enabling the U.S. and its Allies to secure the space environment and counter threats from the ultimate high ground.&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;u&gt;OUR VALUES&lt;/u&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;strong&gt;Be the offset.&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;We create asymmetric advantages with creativity and ingenuity.&lt;/li&gt;
&lt;li class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;strong&gt;What would it take?&lt;/strong&gt;&amp;nbsp;We challenge assumptions to deliver ambitious results.&lt;/li&gt;
&lt;li class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;strong&gt;It’s the people.&lt;/strong&gt; Our team is our competitive advantage and we are better together.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;BENEFITS &amp;amp; PERKS&lt;/span&gt;*&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Best-in-class healthcare: &lt;/strong&gt;100% company-paid medical, dental, and vision coverage for you and your dependents, with HSA/HRA options&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Generous time off: &lt;/strong&gt;Flexible Time Off (FTO) for exempt employees, accrued PTO of up to 25 days for non-exempt employees, plus 12 paid holidays; Parental Leave; Sick Leave&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Fuel for your day: &lt;/strong&gt;Daily catered lunch and unlimited snacks for in-office employees&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;And more: &lt;/strong&gt;401(k) retirement plan, fitness reimbursement, and Dog Fridays&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Equity participation: &lt;/strong&gt;Equity is included as part of our total compensation package, giving you an opportunity to share in the company’s success.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;*Do not apply to fixed term and temporary roles&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW8137857 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW8137857 BCX8&quot;&gt;YOUR MISSION&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW8137857 BCX8&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Creative engineers like you are essential to this mission, to inspire, build, and ship. This is some of the most meaningful work you’ll ever do, in an industry devoted to protecting the people you care about.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are seeking a senior 3D developer with&amp;nbsp;expertise&amp;nbsp;in real-time rendering to join a growing creative team at an early and pivotal moment for the company.&amp;nbsp;You&#39;ll&amp;nbsp;own the visual layer of how we&amp;nbsp;render&amp;nbsp;the common operating&amp;nbsp;picture and 3D information (orbits, spacecraft, sensor volumes, live telemetry) in the browser. This is primarily a React and three.js role, but we will also consider transferable skills from other&amp;nbsp;real-time&amp;nbsp;3D environments such as Unity, Unreal, and&amp;nbsp;Babylon.js.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You’ll&amp;nbsp;work directly with our Creative Director&amp;nbsp;who’s&amp;nbsp;building this team for people who care as much about the craft as the mission.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;RESPONSIBILITIES&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nobody has defined what mission-critical space software should look and feel like.&amp;nbsp;There&#39;s&amp;nbsp;no decade-old design system handed down from a legacy defense contractor to follow.&amp;nbsp;We&#39;re&amp;nbsp;dedicated to building incredible real-time 3D content, directly in the browser, driven by live mission data, at a fidelity operators trust. This is a significant problem, and we need your help.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You’ll&amp;nbsp;have real ownership. From prototypes that shape our product strategy to the views operators depend on in no-fail environments, your work will be&amp;nbsp;visible&amp;nbsp;at the highest levels of government and military. If&amp;nbsp;you’ve&amp;nbsp;ever wanted your craft to carry real weight,&amp;nbsp;then&amp;nbsp;this is that job.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Build and own our React and three.js&amp;nbsp;rendering&amp;nbsp;layer—the 3D viewport and the control measures that make up the common operating&amp;nbsp;picture.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Turn design intent into production front end: components, interaction, motion, and the small details that make an interface feel polished.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Work with our data and platform engineers to render live telemetry and mission data at workable frame rates.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Own the 3D scene craft: renderers, materials and shaders, lighting, camera behavior, and level of detail.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Prototype visual and interaction concepts quickly, so we can test ideas and iterate.&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;QUALIFICATIONS&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Show us things&amp;nbsp;you’ve&amp;nbsp;built&amp;nbsp;– shipped&amp;nbsp;apps, demos, experiments. What runs interests us more than&amp;nbsp;what’s&amp;nbsp;on a CV.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Strong React and TypeScript, with deep three.js or react-three-fiber experience, solid WebGL fundamentals, comfort in GLSL, and a real instinct for performance.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;A strong visual eye. You’re a creative who codes, judging your own work the way a designer would: not just whether it runs, but whether it looks and feels right.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Backgrounds in games, real-time data visualization, creative technology, and interactive agencies all fit here. Defense and space knowledge is welcome, but not expected.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;You won’t be asked to model or texture assets, but fluency with a 3D pipeline (Blender, glTF, texture and geometry budgets) is a plus.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Leverage your experience to work quickly and efficiently, we’re a lean team, everyone needs to pitch in and move fast.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Own your work end to end, from prototype to production, including the polish, the performance, and the hard problems in between.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Turn your hand to what&#39;s needed. Real-time 3D is your focus, but you&#39;ll also take on data visualization and standard front-end work.&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;COMPENSATION&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Base Salary:&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt; $135,000-$195,000&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Equity + Benefits&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; including Health, Dental, Vision, HRA/HSA options, PTO and paid holidays, 401K, Parental Leave&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&lt;em&gt;&lt;span class=&quot;TextRun SCXW83253800 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW83253800 BCX0&quot;&gt;Your actual level and base salary will be&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW83253800 BCX0&quot;&gt;determined&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW83253800 BCX0&quot;&gt; on a case-by-case basis and may vary based on the following considerations: job-related knowledge and skills, education, location, and experience.&lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;span class=&quot;EOP SCXW83253800 BCX0&quot; data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;ADDITIONAL REQUIREMENTS&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Work Location&lt;/strong&gt;—Successful candidates will be located near one of our offices in Long Beach, CA, Denver, CO, or Washington DC. However, for the right candidate we will consider remote.&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Work environment&lt;/strong&gt;—the work environment; temperature, noise level, inside or outside, or other factors that will affect the person&#39;s working conditions while performing the job.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Physical demands&lt;/strong&gt;—the physical demands of the job, including bending, sitting, lifting and driving.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW267002851 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt;This position will be open until it is successfully filled. To &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt;submit&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt; your application, please follow the directions below.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW267002851 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt; &lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;&lt;span class=&quot;NormalTextRun SCXW267002851 BCX0&quot;&gt;#LI-Hybrid&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: rgb(224, 62, 45);&quot;&gt;&lt;strong&gt;&lt;span class=&quot;EOP SCXW267002851 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;To conform to U.S. Government space technology export regulations, including the International Traffic in Arms Regulations (ITAR) you must be a U.S. citizen, lawful permanent resident of the U.S., protected individual as defined by 8 U.S.C. 1324b(a)(3), or eligible to obtain the required authorizations from the U.S. Department of State.&lt;/p&gt;
&lt;p&gt;True Anomaly is committed to equal employment opportunity on any basis protected by applicable state and federal laws. If you have a disability or additional need that requires accommodation, please do not hesitate to let us know.&lt;/p&gt;
&lt;p&gt;To protect candidates and our company from application fraud and impersonation, we use third-party tools to verify applicant identity and detect fraudulent applications. Learn more in our &lt;a href=&quot;https://www.trueanomaly.space/legal/privacy-policy&quot; target=&quot;_blank&quot;&gt;Privacy Notice&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;Space is a warfighting domain. True Anomaly seeks those with the talent and ambition to build the technology that secures it.&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;u&gt;OUR MISSION&lt;/u&gt;&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;True Anomaly delivers decisive capabilities for space superiority. We build autonomous spacecraft, advanced payloads, mission software, and space-based interceptors — enabling the U.S. and its Allies to secure the space environment and counter threats from the ultimate high ground.&lt;/p&gt;
&lt;p class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;u&gt;OUR VALUES&lt;/u&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;strong&gt;Be the offset.&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;We create asymmetric advantages with creativity and ingenuity.&lt;/li&gt;
&lt;li class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;strong&gt;What would it take?&lt;/strong&gt;&amp;nbsp;We challenge assumptions to deliver ambitious results.&lt;/li&gt;
&lt;li class=&quot;ms-outlook-mobile-reference-message&quot;&gt;&lt;strong&gt;It’s the people.&lt;/strong&gt; Our team is our competitive advantage and we are better together.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;BENEFITS &amp;amp; PERKS&lt;/span&gt;*&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Best-in-class healthcare: &lt;/strong&gt;100% company-paid medical, dental, and vision coverage for you and your dependents, with HSA/HRA options&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Generous time off: &lt;/strong&gt;Flexible Time Off (FTO) for exempt employees, accrued PTO of up to 25 days for non-exempt employees, plus 12 paid holidays; Parental Leave; Sick Leave&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Fuel for your day: &lt;/strong&gt;Daily catered lunch and unlimited snacks for in-office employees&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;And more: &lt;/strong&gt;401(k) retirement plan, fitness reimbursement, and Dog Fridays&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Equity participation: &lt;/strong&gt;Equity is included as part of our total compensation package, giving you an opportunity to share in the company’s success.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;*Do not apply to fixed term and temporary roles&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;RESPONSIBILITIES&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Own end-to-end development of spacecraft Guidance, Navigation, and Control (GNC) systems, including architecture definition, algorithm design, software implementation, hardware integration, verification, and flight operations&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Design, test, and validate GNC flight software for spacecraft operating in LEO, GEO, and cislunar environments&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Develop advanced attitude and orbit determination algorithms, including sensor fusion, state estimation, covariance analysis, and Kalman filtering (EKF/UKF/batch)&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Design control laws for attitude control, orbit control, maneuver execution, and closed-loop guidance, ensuring required performance and robustness under uncertainties&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Lead creation and improvement of high-fidelity 6-DOF simulations, sensor/actuator models, disturbance environments, Monte Carlo pipelines, and SIL/HIL integration&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Conduct system-level GNC trade studies and develop recommendations for hardware such as reaction wheels, torque rods, thrusters, star trackers, IMUs, GNSS units, and optical navigation sensors&lt;/li&gt;
