&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valve and/or propellant tank design, analysis, and manufacturing experience. &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
