&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bachelor&#39;s degree in aerospace engineering, mechanical engineering, computer science, physics, a similar discipline, or equivalent practical experience&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
