&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;U.S. Citizen and eligible for DoD Secret or TS/SCI clearance&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
