&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Lead architectural improvements through hands-on implementation, prototyping, debugging, and technical&amp;nbsp;excellence.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
